from billing.calendar import add_months, cycle_bounds
checked = 0
for year in (1999, 2000, 2024, 2026, 2096, 2100):
    for month in range(1, 13):
        for day in (28, 29, 30, 31):
            try:
                anchor = date(year, month, day)
