                    start = add_months(anchor, k * step)
                    end = add_months(anchor, (k + 1) * step)
                    for on in (start, start + (end - start) // 2, end - timedelta(days=1)):
                        assert cycle_bounds(anchor, on, interval) == (start, end), (anchor, on, interval)
                        checked += 1
print(f'Calendar cross-check passed: {checked} boundary/mid-cycle dates')
